for (let seed = 501; seed <= 1000; seed++) {
  const { result } = await runTrial({ THREE, CANNON, desc, seed });
  if (result.success) pass++; else fails.push(result);
}
console.log(`501..1000: ${pass}/500 (${(pass/5).toFixed(2)}%)`);
for (const f of fails) {
  const tr = trial(f.seed);
  console.log(`  FAIL ${f.seed}: ${f.reason} final=${JSON.stringify(f.final)} bumps=${JSON.stringify(f.bumpTimes)} rest=${tr.restitution.toFixed(2)} fric=${tr.friction.toFixed(2)}`);
}
'

